class Solution {
  public long maxWeight(int[] pizzas) {
    java.util.Arrays.sort(pizzas);
    int days = pizzas.length / 4, hi = pizzas.length - 1;
    long total = 0;
    for (int d = 1; d <= days; d++) {
      if ((d & 1) == 1) {
        total += pizzas[hi];
        hi--;
      } else {
        total += pizzas[hi - 1];
        hi -= 2;
      }
    }
    return total;
  }
}
